<?php namespace App; use Illuminate\Database\Eloquent\Model; class EmergencyEncounter extends Model {protected $guarded=[];protected $casts=['danger_signs'=>'array','immediate_actions'=>'array'];protected $dates=['arrival_at','doctor_acknowledged_at'];public function patient(){return $this->belongsTo(Patient::class);}public function doctor(){return $this->belongsTo(User::class,'assigned_doctor_id');}public function creator(){return $this->belongsTo(User::class,'created_by');}}
